import base64, re, sys
EXCL_B64 = ""
excl_raw = base64.b64decode(EXCL_B64).decode()
excl = set(line.strip() for line in excl_raw.splitlines() if line.strip())
fresh = []
seen = set()
with open('cand_D_uniq.tsv') as f:
    for line in f:
        parts = line.rstrip('\n').split('\t')
        if len(parts) < 4: continue
        mc = int(parts[0])
        sf = parts[1]
        user = parts[2]
        host = parts[3]
        tools = parts[4] if len(parts) > 4 else ''
        base = re.sub(r'\.messages(\.archive)?\.json$','',sf)
        if base in excl or base in seen:
            continue
        seen.add(base)
        fresh.append((mc, sf, user, host, tools))
fresh.sort(key=lambda x: -x[0])
with open('fresh_D.tsv','w') as f:
    for mc, sf, user, host, tools in fresh:
        f.write(f'{mc}\t{sf}\t{user}\t{host}\t{tools}\n')
print(f'fresh={len(fresh)}')
for mc, sf, user, host, tools in fresh[:30]:
    print(mc, sf, user, host, tools[:80])
